package com.donotmiss.backend.aiapplication.career;
import com.donotmiss.backend.common.CurrentUser; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/career/resumes") public class ResumeCareerController{
 private final ResumeCareerApplicationService service; private final CurrentUser currentUser; public ResumeCareerController(ResumeCareerApplicationService service,CurrentUser currentUser){this.service=service;this.currentUser=currentUser;}
 @PostMapping public ResumeDtos.ResumeVersionResponse create(@Valid @RequestBody ResumeDtos.CreateResumeVersionRequest body,HttpServletRequest request){return service.createVersion(currentUser.id(request),body);} @PostMapping("/{resumeVersionId}/parse") public ResumeDtos.CandidateProfileResponse parse(@PathVariable Long resumeVersionId,HttpServletRequest request){return service.parse(currentUser.id(request),resumeVersionId);} @GetMapping public List<ResumeDtos.ResumeVersionResponse> list(HttpServletRequest request){return service.versions(currentUser.id(request));} @GetMapping("/{resumeVersionId}") public ResumeDtos.ResumeVersionResponse get(@PathVariable Long resumeVersionId,HttpServletRequest request){return service.getVersion(currentUser.id(request),resumeVersionId);} @GetMapping("/{resumeVersionId}/profile") public ResumeDtos.CandidateProfileResponse profile(@PathVariable Long resumeVersionId,HttpServletRequest request){return service.profile(currentUser.id(request),resumeVersionId);} @GetMapping("/{resumeVersionId}/evidences") public List<ResumeDtos.CandidateEvidenceResponse> evidence(@PathVariable Long resumeVersionId,HttpServletRequest request){return service.evidence(currentUser.id(request),resumeVersionId);}
}
